#include <bits/stdc++.h>
#define ll long long
using namespace std;

int main()
{
    ll h, n;
    cin >> h >> n;

    ll nodes = pow(2, h + 1) - 1;

    vector<ll> v;
    v.push_back(n);

    for (int i = 0; i < h; i++)
    {
        n = n / 2 + n % 2;
        v.push_back(n);
    }

    sort(v.begin(), v.end());
    char s = 'L';
    ll visited = 0;

    for (int i = 0; i < h; i++)
    {
        ll curnodes = pow(2, h - i + 1) - 2;
        visited++;

        if (s == 'L')
        {
            if (v[i + 1] % 2 != 0)
                s = 'R';
            else
                visited += max(curnodes / 2, 0LL);
        }
        else if (s == 'R')
        {
            if (v[i + 1] % 2 == 0)
                s = 'L';
            else
                visited += max(curnodes / 2, 0LL);
        }
    }

    cout << visited << endl;

    return 0;
}

